/**
 * Database schema (PostgreSQL, Drizzle ORM). Minimum tables from brief §8.2.
 * Conventions:
 *  - UUID primary keys generated by Postgres.
 *  - All timestamps are timestamptz.
 *  - Secrets (access tokens, session tokens) are stored ONLY as SHA-256 hashes.
 */
import { sql } from "drizzle-orm";
import {
  boolean,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

const id = () => uuid("id").primaryKey().default(sql`gen_random_uuid()`);
const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();

// ---------- Enums ----------
export const planTierEnum = pgEnum("plan_tier", ["basic", "premium"]);
export const billingPeriodEnum = pgEnum("billing_period", ["monthly", "yearly"]);
export const subscriptionStatusEnum = pgEnum("subscription_status", [
  "active",
  "past_due", // grace period
  "canceled", // keeps access until current_period_end
  "revoked", // refund / chargeback: access removed immediately
  "expired",
]);
export const hotmartEventStatusEnum = pgEnum("hotmart_event_status", ["pending", "processed", "failed", "ignored"]);
export const accessTokenPurposeEnum = pgEnum("access_token_purpose", ["welcome", "login", "device_change"]);
export const deviceStatusEnum = pgEnum("device_status", ["active", "revoked", "pending_review"]);
export const legalKindEnum = pgEnum("legal_kind", ["terms", "privacy", "cookies"]);
export const availabilityEnum = pgEnum("availability", ["free", "locked", "soon"]);
export const mediaStatusEnum = pgEnum("media_status", ["uploading", "processing", "ready", "error"]);
export const signupListEnum = pgEnum("signup_list", ["gift", "app_launch"]);

// ---------- Users & billing ----------
export const users = pgTable("users", {
  id: id(),
  email: text("email").notNull(),
  name: text("name"),
  isAdmin: boolean("is_admin").notNull().default(false),
  createdAt: createdAt(),
  deletedAt: timestamp("deleted_at", { withTimezone: true }),
}, (t) => [uniqueIndex("users_email_lower_uq").on(sql`lower(${t.email})`)]);

export const subscriptions = pgTable("subscriptions", {
  id: id(),
  userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  planKey: text("plan_key").notNull(), // key in config/plans.ts
  tier: planTierEnum("tier").notNull(),
  period: billingPeriodEnum("period").notNull(),
  status: subscriptionStatusEnum("status").notNull(),
  hotmartSubscriberCode: text("hotmart_subscriber_code"),
  hotmartTransaction: text("hotmart_transaction"),
  currentPeriodEnd: timestamp("current_period_end", { withTimezone: true }),
  graceUntil: timestamp("grace_until", { withTimezone: true }),
  createdAt: createdAt(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  index("subscriptions_user_idx").on(t.userId),
  uniqueIndex("subscriptions_hotmart_subscriber_uq").on(t.hotmartSubscriberCode),
]);

export const entitlements = pgTable("entitlements", {
  userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  key: text("key").notNull(), // catalog | breathing | sounds | custom_meditation | community
  subscriptionId: uuid("subscription_id").references(() => subscriptions.id, { onDelete: "cascade" }),
  grantedAt: createdAt(),
  expiresAt: timestamp("expires_at", { withTimezone: true }),
}, (t) => [primaryKey({ columns: [t.userId, t.key] })]);

export const hotmartEvents = pgTable("hotmart_events", {
  id: id(),
  hotmartEventId: text("hotmart_event_id").notNull(), // idempotency key from the postback
  eventType: text("event_type").notNull(),
  environment: text("environment").notNull(), // sandbox | production
  payload: jsonb("payload").notNull(),
  status: hotmartEventStatusEnum("status").notNull().default("pending"),
  attempts: integer("attempts").notNull().default(0),
  lastError: text("last_error"),
  receivedAt: createdAt(),
  processedAt: timestamp("processed_at", { withTimezone: true }),
}, (t) => [
  uniqueIndex("hotmart_events_event_id_uq").on(t.hotmartEventId),
  index("hotmart_events_status_idx").on(t.status),
]);

// ---------- Access ----------
export const accessTokens = pgTable("access_tokens", {
  id: id(),
  userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  tokenHash: text("token_hash").notNull(),
  purpose: accessTokenPurposeEnum("purpose").notNull(),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  usedAt: timestamp("used_at", { withTimezone: true }),
  createdAt: createdAt(),
}, (t) => [uniqueIndex("access_tokens_hash_uq").on(t.tokenHash)]);

export const devices = pgTable("devices", {
  id: id(),
  userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  label: text("label").notNull(), // readable browser + OS, e.g. "Safari en iPhone"
  status: deviceStatusEnum("status").notNull().default("active"),
  createdAt: createdAt(),
  lastSeenAt: timestamp("last_seen_at", { withTimezone: true }),
  revokedAt: timestamp("revoked_at", { withTimezone: true }),
}, (t) => [
  index("devices_user_idx").on(t.userId),
  // At most one active device per account, enforced by the database.
  uniqueIndex("devices_one_active_per_user_uq").on(t.userId).where(sql`${t.status} = 'active'`),
]);

export const sessions = pgTable("sessions", {
  id: id(),
  userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  deviceId: uuid("device_id").notNull().references(() => devices.id, { onDelete: "cascade" }),
  tokenHash: text("token_hash").notNull(),
  createdAt: createdAt(),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  revokedAt: timestamp("revoked_at", { withTimezone: true }),
  // Single active playback per account (heartbeat).
  playbackHeartbeatAt: timestamp("playback_heartbeat_at", { withTimezone: true }),
}, (t) => [
  uniqueIndex("sessions_token_hash_uq").on(t.tokenHash),
  index("sessions_user_idx").on(t.userId),
]);

// ---------- Legal ----------
export const legalDocuments = pgTable("legal_documents", {
  id: id(),
  kind: legalKindEnum("kind").notNull(),
  version: text("version").notNull(),
  title: text("title").notNull(),
  body: text("body").notNull(),
  publishedAt: timestamp("published_at", { withTimezone: true }),
  createdAt: createdAt(),
}, (t) => [uniqueIndex("legal_documents_kind_version_uq").on(t.kind, t.version)]);

export const legalAcceptances = pgTable("legal_acceptances", {
  id: id(),
  userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  documentId: uuid("document_id").notNull().references(() => legalDocuments.id),
  deviceId: uuid("device_id").references(() => devices.id, { onDelete: "set null" }),
  acceptedAt: createdAt(),
}, (t) => [uniqueIndex("legal_acceptances_user_doc_uq").on(t.userId, t.documentId)]);

// ---------- Content ----------
export const mediaAssets = pgTable("media_assets", {
  id: id(),
  provider: text("provider").notNull(), // mux | cloudflare | s3
  providerAssetId: text("provider_asset_id").notNull(),
  status: mediaStatusEnum("status").notNull().default("uploading"),
  durationSeconds: integer("duration_seconds"),
  sourceFilename: text("source_filename"),
  createdAt: createdAt(),
}, (t) => [uniqueIndex("media_assets_provider_asset_uq").on(t.provider, t.providerAssetId)]);

export const meditations = pgTable("meditations", {
  id: id(),
  slug: text("slug").notNull(),
  title: text("title").notNull(),
  group: text("group").notNull(),
  durationSeconds: integer("duration_seconds"),
  description: text("description"),
  availability: availabilityEnum("availability").notNull().default("soon"),
  minTier: planTierEnum("min_tier"), // null = free for everyone
  sortOrder: integer("sort_order").notNull().default(0),
  mediaAssetId: uuid("media_asset_id").references(() => mediaAssets.id, { onDelete: "set null" }),
  createdAt: createdAt(),
}, (t) => [uniqueIndex("meditations_slug_uq").on(t.slug), index("meditations_group_idx").on(t.group, t.sortOrder)]);

export const playbackProgress = pgTable("playback_progress", {
  userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
  meditationId: uuid("meditation_id").notNull().references(() => meditations.id, { onDelete: "cascade" }),
  positionSeconds: integer("position_seconds").notNull().default(0),
  completedAt: timestamp("completed_at", { withTimezone: true }),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
}, (t) => [primaryKey({ columns: [t.userId, t.meditationId] })]);

// ---------- Lead capture (landing gift, app launch notice) ----------
export const emailSignups = pgTable("email_signups", {
  id: id(),
  list: signupListEnum("list").notNull(),
  email: text("email").notNull(),
  name: text("name"),
  // GDPR: explicit consent timestamp and the privacy-policy version shown at that moment.
  consentAt: timestamp("consent_at", { withTimezone: true }).notNull(),
  privacyVersion: text("privacy_version").notNull(),
  createdAt: createdAt(),
  unsubscribedAt: timestamp("unsubscribed_at", { withTimezone: true }),
}, (t) => [uniqueIndex("email_signups_list_email_uq").on(t.list, t.email)]);

// ---------- Audit ----------
export const auditLog = pgTable("audit_log", {
  id: id(),
  actorUserId: uuid("actor_user_id").references(() => users.id, { onDelete: "set null" }),
  action: text("action").notNull(), // e.g. login, device_changed, legal_accepted, hotmart_event, admin_*
  subjectType: text("subject_type"),
  subjectId: text("subject_id"),
  metadata: jsonb("metadata"),
  createdAt: createdAt(),
}, (t) => [index("audit_log_created_idx").on(t.createdAt), index("audit_log_actor_idx").on(t.actorUserId)]);
